import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { useReducedMotion } from '@/hooks/use-reduced-motion'

const progressBarVariants = cva('relative block w-full overflow-hidden rounded-full', {
  variants: {
    size: {
      xs: 'h-[3px]',
      sm: 'h-1',
      md: 'h-2',
      lg: 'h-3',
    },
  },
  defaultVariants: { size: 'md' },
})

// Dot diameter per size -- the segment geometry (gaps, pill width, the faint
// filler pattern) derives from it. Keep in sync with the height classes above.
const DOT_PX = { xs: 3, sm: 4, md: 8, lg: 12 } as const

// Segment accumulation: every SEGMENT_SPAN filled dots collapse into one solid
// pill of PILL_DOT_FACTOR dot-widths, so an open-ended tally stays compact.
const SEGMENT_SPAN = 10
const PILL_DOT_FACTOR = 3

export interface ProgressBarProps extends VariantProps<typeof progressBarVariants> {
  /** Progress as a fraction from 0 to 1 (clamped). Ignored when `indeterminate`. */
  value?: number
  /**
   * Open-ended / no-target progress. With `count` it renders segment
   * accumulation (see `count`); without one it renders the plain dotted accent
   * line. The static counterpart to a native <progress> with no value -- it
   * means "unbounded", not "loading", so it does not animate. Used for
   * Chip Away's free-streak / count goals.
   */
  indeterminate?: boolean
  /**
   * The tally behind an `indeterminate` bar (check-ins, streak days, ...).
   * Renders segment accumulation: each unit fills one solid accent dot on a row
   * of faint track-colored dots, and every 10 filled dots collapse into a solid
   * pill a few dot-widths wide -- so the tally can grow past the track width.
   * 0 shows the all-faint default state. Ignored without `indeterminate`.
   */
  count?: number
  /**
   * Work is in flight and its next step cannot be counted yet.
   *
   * Distinct from `indeterminate`, which means *unbounded* and renders a static
   * dotted line: `busy` is *loading*, and lays a sweeping accent band over the
   * track. Combine it with a `value` for a run whose stages are only partly
   * countable -- the bar holds its fill and keeps a sign of life through the
   * stage that cannot report a count. Reduced motion holds the band still, so
   * the surrounding text has to carry the meaning either way.
   */
  busy?: boolean
  /**
   * Accessible label. With a value the bar exposes role="progressbar" +
   * aria-valuenow (indeterminate omits aria-valuenow, per ARIA). Omit, or pass
   * `decorative`, when adjacent text already conveys the value (e.g. the TabBar
   * underline beneath a "Day 6 of 10" line).
   */
  label?: string
  /** Render purely decorative (aria-hidden, no role). */
  decorative?: boolean
  className?: string
  /** Inline styles for the root element. */
  style?: React.CSSProperties
}

const trackColor =
  'var(--wj-progress-track, color-mix(in srgb, var(--color-accent-500) 35%, transparent))'

/**
 * Progress bar / indicator. Rendered with <span>s (display fixed via classes)
 * so it can sit inside a <button> (e.g. a sidebar tab item). Uses, mirroring a
 * tab underline's states: a 0..1 `value` is a determinate fill (accent fill
 * over a low-opacity accent track); `indeterminate` + `count` is segment
 * accumulation (open-ended tally); `indeterminate` alone is a dotted accent
 * line; neither is just an empty track.
 */
export const ProgressBar = React.forwardRef<HTMLSpanElement, ProgressBarProps>(function ProgressBar({
  value = 0,
  indeterminate,
  count,
  busy,
  size,
  label,
  decorative,
  className,
  style,
}, ref) {
  const reduced = useReducedMotion()
  const pct = Math.round(Math.max(0, Math.min(1, value)) * 100)

  const a11y = decorative
    ? ({ 'aria-hidden': true } as const)
    : {
        role: 'progressbar' as const,
        'aria-valuemin': 0,
        'aria-valuemax': 100,
        // Indeterminate progress omits aria-valuenow.
        ...(indeterminate ? {} : { 'aria-valuenow': pct }),
        ...(label ? { 'aria-label': label } : {}),
        // A bar that is working but cannot say how far along it is says so,
        // rather than reporting a number that will not move.
        ...(busy ? { 'aria-busy': true } : {}),
      }

  if (indeterminate && count != null) {
    const dot = DOT_PX[size ?? 'md']
    const tally = Math.max(0, Math.floor(count))
    const pills = Math.floor(tally / SEGMENT_SPAN)
    const dots = tally % SEGMENT_SPAN
    return (
      <span ref={ref} className={cn(progressBarVariants({ size }), 'bg-transparent', className)} style={style} {...a11y}>
        {/* Gap equals the dot size (the dotted line's rhythm: dot-sized gaps). */}
        <span className="flex h-full w-full items-center" style={{ gap: `${dot}px` }}>
          {Array.from({ length: pills }, (_, i) => (
            // Pills may shrink (down to a dot) when a large tally outgrows the
            // width -- the newest pills and the current batch stay visible.
            <span
              key={`pill-${i}`}
              className="block h-full rounded-full bg-[var(--color-accent-500)]"
              style={{ width: dot * PILL_DOT_FACTOR, minWidth: dot }}
            />
          ))}
          {Array.from({ length: dots }, (_, i) => (
            <span
              key={`dot-${i}`}
              className="block h-full shrink-0 rounded-full bg-[var(--color-accent-500)]"
              style={{ width: dot }}
            />
          ))}
          {/* Faint dots fill whatever width remains -- a repeating pattern in
              the track color, phase-aligned with the flex gap so the rhythm is
              unbroken. The right edge ends wherever the pattern lands. */}
          <span
            className="block h-full min-w-0 flex-1"
            style={{
              backgroundImage: `radial-gradient(circle at ${dot / 2}px center, ${trackColor} ${dot / 2}px, transparent ${dot / 2}px)`,
              backgroundSize: `${dot * 2}px 100%`,
              backgroundPosition: 'left center',
              backgroundRepeat: 'repeat-x',
            }}
          />
        </span>
      </span>
    )
  }

  if (indeterminate) {
    return (
      <span ref={ref} className={cn(progressBarVariants({ size }), 'bg-transparent', className)} style={style} {...a11y}>
        <span
          className="block h-full w-full"
          // Round dots repeating from the left, evenly spaced with the gap equal to
          // the dot size (3px dot, 3px gap; 6px period). The right edge ends wherever
          // the pattern lands. Tunable via the 1.5px radius + the 6px period.
          style={{
            backgroundImage:
              'radial-gradient(circle at 1.5px center, var(--color-accent-500) 1.5px, transparent 1.5px)',
            backgroundSize: '6px 100%',
            backgroundPosition: 'left center',
            backgroundRepeat: 'repeat-x',
          }}
        />
      </span>
    )
  }

  return (
    <span
      ref={ref}
      className={cn(progressBarVariants({ size }), className)}
      // Track: accent at low opacity, so it carries no bevel -- a hairline over
      // a color-mix against transparent reads as haze rather than an edge.
      // Override --wj-progress-track to tune / theme.
      // Caller style merges last so it can override the track color.
      style={{ backgroundColor: trackColor, ...style }}
      {...a11y}
    >
      <span
        className={cn(
          'block h-full rounded-full bg-[var(--color-accent-500)]',
          // The fill is solid, so it can hold an edge -- but a decorative bar is
          // a TabBar / SidebarTabs underline, 3px tall and clipped by the tab's
          // corners. A hairline there is noise, and the plain solid underline
          // beside it carries none, so the two would not match.
          !decorative && 'shadow-bevel-accent',
          !reduced && 'transition-[width] duration-300 ease-out'
        )}
        style={{ width: `${pct}%` }}
      />
      {/* The busy sweep rides the whole track, over the fill, so a bar that is
          holding at 15% through an uncountable stage still reads as working.
          The utility carries its own reduced-motion backstop. */}
      {busy && (
        <span aria-hidden className="wj-busy-sweep absolute inset-0 rounded-full" />
      )}
    </span>
  )
})

ProgressBar.displayName = 'ProgressBar'
